#include <stdio.h>

int main(void) {
    int a = 5;
    int b = a++ + 2;
    printf("a = %d, b = %d\n", a, b);

    int x = 7 / 2;
    float y = 7 / 2.0f;
    printf("x = %d, y = %.1f\n", x, y);

    char s[] = "Goa";
    printf("sizeof = %zu\n", sizeof(s));
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    string name = "Xecxec";
    cout << "Hello from C++, " << name << "!" << endl;
    return 0;
}

